def transform(grid):
    n = len(grid)
    m = len(grid[0])
    out = [[7] * m for _ in range(n)]
    cr, cc = n // 2, m // 2
    color = grid[cr][cc]

    if color != 7:
        # The central cell belongs to the selected quadrant; extend its
        # diagonal from the centre to that quadrant's outer corner.
        found = None
        for r in range(n):
            for c in range(m):
                if grid[r][c] == color and (r != cr or c != cc):
                    found = (r, c)
                    break
            if found:
                break
        dr = 1 if found and found[0] > cr else -1
        dc = 1 if found and found[1] > cc else -1
        r, c = cr, cc
        while 0 <= r < n and 0 <= c < m:
            out[r][c] = color
            r += dr
            c += dc
    else:
        # With a blank centre, the selected object is in the upper right.
        color = next(grid[r][c] for r in range(cr) for c in range(cc + 1, m)
                     if grid[r][c] != 7)
        for i in range(cr + 1):
            out[i][m - 1 - i] = color

    return out
